public class CharChampion {

    public static char mostFrequentChar(String s) {
        if (s.isEmpty()) {
            return '?';
        }
        char best = s.charAt(0);
        int bestCount = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (s.indexOf(c) != i) {
                continue; // only handle each char at its first occurrence
            }
            int count = 0;
            for (int j = 0; j < s.length(); j++) {
                if (s.charAt(j) == c) {
                    count++;
                }
            }
            if (count > bestCount) {
                bestCount = count;
                best = c;
            }
        }
        return best;
    }
}
